25	func newMigrateCmd() *cobra.Command {
26		var checkpointsFlag string
27	
28		cmd := &cobra.Command{
29			Use:    "migrate",
30			Short:  "Migrate Entire data to newer formats",
31			Long:   `Migrate Entire data to newer formats. Currently supports migrating v1 checkpoints to v2.`,
32			Hidden: true,
33			RunE: func(cmd *cobra.Command, _ []string) error {
34				if checkpointsFlag == "" {
35					return cmd.Help()
36				}
37				if checkpointsFlag != "v2" {
38					return fmt.Errorf("unsupported checkpoints version: %q (only \"v2\" is supported)", checkpointsFlag)
39				}
40	
41				ctx := cmd.Context()
42	
43				if _, err := paths.WorktreeRoot(ctx); err != nil {
44					cmd.SilenceUsage = true
45					fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
46					return NewSilentError(errors.New("not a git repository"))
47				}
48	
49				logging.SetLogLevelGetter(GetLogLevel)
50				if initErr := logging.Init(ctx, ""); initErr != nil {
51					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not initialize logging: %v\n", initErr)
52				} else {
53					defer logging.Close()
54				}
55				return runMigrateCheckpointsV2(ctx, cmd)
56			},
57		}
58	
59		cmd.Flags().StringVar(&checkpointsFlag, "checkpoints", "", "Target checkpoint format version (e.g., \"v2\")")
60	
61		return cmd
62	}
