70	func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command) error {
71		repo, err := strategy.OpenRepository(ctx)
72		if err != nil {
73			cmd.SilenceUsage = true
74			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
75			return NewSilentError(err)
76		}
77	
78		v1Store := checkpoint.NewGitStore(repo)
79		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
80		out := cmd.OutOrStdout()
81	
82		result, err := migrateCheckpointsV2(ctx, repo, v1Store, v2Store, out)
83		if err != nil {
84			return err
85		}
86	
87		fmt.Fprintf(out, "\nMigration complete: %d migrated, %d skipped, %d failed\n",
88			result.migrated, result.skipped, result.failed)
89	
90		if result.failed > 0 {
91			fmt.Fprintf(out, "%d checkpoint(s) failed to migrate. Check .entire/logs/ for details.\n", result.failed)
92			return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
93		}
94	
95		return nil
96	}
