105	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, out io.Writer) (*migrateResult, error) {
106		v1List, err := v1Store.ListCommitted(ctx)
107		if err != nil {
108			return nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
109		}
110	
111		if len(v1List) == 0 {
112			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
113			return &migrateResult{}, nil
114		}
115	
116		fmt.Fprintln(out, "Migrating v1 checkpoints to v2...")
117		total := len(v1List)
118		result := &migrateResult{}
119	
120		for i, info := range v1List {
121			prefix := fmt.Sprintf("  [%d/%d] Migrating checkpoint %s...", i+1, total, info.CheckpointID)
122	
123			if migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, out, prefix); migrateErr != nil {
124				switch {
125				case errors.Is(migrateErr, errAlreadyMigrated):
126					fmt.Fprintf(out, "%s skipped (already in v2)\n", prefix)
127					result.skipped++
128				case errors.Is(migrateErr, errTranscriptNotGeneratable):
129					fmt.Fprintf(out, "%s in v2, but %s\n", prefix, migrateErr.Error())
130					result.skipped++
131				default:
132					fmt.Fprintf(out, "%s failed\n", prefix)
133					logging.Error(ctx, "checkpoint migration failed",
134						slog.String("checkpoint_id", string(info.CheckpointID)),
135						slog.String("error", migrateErr.Error()),
136					)
137					result.failed++
138				}
139				continue
140			}
141	
142			result.migrated++
143		}
144	
145		return result, nil
146	}
