148	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, out io.Writer, prefix string) error {
149		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
150		if err != nil {
151			return fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
152		}
153	
154		// Already in v2 — check if any aspect of sessions are missing and backfill
155		if existing != nil {
156			repaired, repairErr := repairPartialV2Checkpoint(ctx, repo, v1Store, v2Store, info, existing)
157			if repairErr != nil {
158				return repairErr
159			}
160	
161			currentV2, readCurrentErr := v2Store.ReadCommitted(ctx, info.CheckpointID)
162			if readCurrentErr != nil {
163				return fmt.Errorf("failed to re-read v2 checkpoint %s: %w", info.CheckpointID, readCurrentErr)
164			}
165			if currentV2 == nil {
166				return fmt.Errorf("v2 checkpoint %s disappeared during migration", info.CheckpointID)
167			}
168	
169			backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, currentV2, out, prefix)
170			if errors.Is(backfillErr, errAlreadyMigrated) && repaired {
171				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state\n", prefix)
172				return nil
173			}
174			if errors.Is(backfillErr, errTranscriptNotGeneratable) && repaired {
175				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state (compact transcript not generated)\n", prefix)
176				return nil
177			}
178			return backfillErr
179		}
180	
181		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
182		if err != nil {
183			return fmt.Errorf("failed to read v1 summary: %w", err)
184		}
185		if summary == nil {
186			return fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
187		}
188	
189		compactFailed := false
190		shouldCopyTaskMetadata := false
191	
192		for sessionIdx := range len(summary.Sessions) {
193			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
194			if readErr != nil {
195				return fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
196			}
197			if content.Metadata.IsTask {
198				shouldCopyTaskMetadata = true
199			}
200	
201			opts := buildMigrateWriteOpts(content, info)
202	
203			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
204			if compacted != nil {
205				opts.CompactTranscript = compacted
206			} else if len(content.Transcript) > 0 {
207				compactFailed = true
208			}
209	
210			if writeErr := v2Store.WriteCommitted(ctx, opts); writeErr != nil {
211				return fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
212			}
213		}
214	
215		// Copy task metadata trees from v1 to v2 /full/current
216		if shouldCopyTaskMetadata {
217			if taskErr := copyTaskMetadataToV2(repo, v1Store, v2Store, info.CheckpointID, summary); taskErr != nil {
218				logging.Warn(ctx, "failed to copy task metadata to v2",
219					slog.String("checkpoint_id", string(info.CheckpointID)),
220					slog.String("error", taskErr.Error()),
221				)
222			}
223		}
224	
225		if compactFailed {
226			fmt.Fprintf(out, "%s done (compact transcript not generated)\n", prefix)
227		} else {
228			fmt.Fprintf(out, "%s done\n", prefix)
229		}
230	
231		return nil
232	}
