234	func repairPartialV2Checkpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (bool, error) {
235		repaired := false
236	
237		// Spot-check already present sessions: ensure required /full/current artifacts exist.
238		existingSessionCount := len(v2Summary.Sessions)
239		for sessionIdx := range existingSessionCount {
240			ok, checkErr := hasCurrentFullSessionArtifacts(repo, v2Store, info.CheckpointID, sessionIdx)
241			if checkErr != nil {
242				return false, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
243			}
244			if ok {
245				continue
246			}
247	
248			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
249			if readErr != nil {
250				return false, fmt.Errorf("failed to read v1 session %d while repairing v2: %w", sessionIdx, readErr)
251			}
252	
253			updateOpts := checkpoint.UpdateCommittedOptions{
254				CheckpointID: info.CheckpointID,
255				SessionID:    content.Metadata.SessionID,
256				Transcript:   content.Transcript,
257				Prompts:      checkpoint.SplitPromptContent(content.Prompts),
258				Agent:        content.Metadata.Agent,
259			}
260			if compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata); compacted != nil {
261				updateOpts.CompactTranscript = compacted
262			}
263	
264			if updateErr := v2Store.UpdateCommitted(ctx, updateOpts); updateErr != nil {
265				return false, fmt.Errorf("failed to repair v2 session %d: %w", sessionIdx, updateErr)
266			}
267			repaired = true
268		}
269	
270		return repaired, nil
271	}
