273	func hasCurrentFullSessionArtifacts(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int) (bool, error) {
274		_, rootTreeHash, err := v2Store.GetRefState(plumbing.ReferenceName(paths.V2FullCurrentRefName))
275		if err != nil {
276			return false, nil //nolint:nilerr // Missing /full/current ref means required artifacts are absent.
277		}
278	
279		rootTree, err := repo.TreeObject(rootTreeHash)
280		if err != nil {
281			return false, fmt.Errorf("failed to read /full/current tree: %w", err)
282		}
283	
284		sessionPath := fmt.Sprintf("%s/%d", cpID.Path(), sessionIdx)
285		sessionTree, err := rootTree.Tree(sessionPath)
286		if err != nil {
287			return false, nil //nolint:nilerr // Missing session path means artifacts are absent, not a hard error.
288		}
289	
290		hasTranscript := false
291		for _, entry := range sessionTree.Entries {
292			if entry.Name == paths.TranscriptFileName || strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
293				hasTranscript = true
294				break
295			}
296		}
297		if !hasTranscript {
298			return false, nil
299		}
300	
301		if _, err := sessionTree.File(paths.ContentHashFileName); err != nil {
302			return false, nil //nolint:nilerr // Missing content hash indicates incomplete /full/current artifacts.
303		}
304	
305		return true, nil
306	}
