308	// backfillCompactTranscripts checks sessions in an already-migrated v2 checkpoint
309	// for missing transcript.jsonl and attempts to generate + write them from v1 data.
310	// Returns errAlreadyMigrated if all sessions already have compact transcripts.
311	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary, out io.Writer, prefix string) error {
312		// Find sessions missing transcript.jsonl
313		var needsBackfill []int
314		for i, session := range v2Summary.Sessions {
315			if session.Transcript == "" {
316				needsBackfill = append(needsBackfill, i)
317			}
318		}
319	
320		if len(needsBackfill) == 0 {
321			return errAlreadyMigrated
322		}
323	
324		backfilled := 0
325		var lastAgent string
326	
327		for _, sessionIdx := range needsBackfill {
328			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
329			if readErr != nil {
330				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
331					slog.String("checkpoint_id", string(info.CheckpointID)),
332					slog.Int("session_index", sessionIdx),
333					slog.String("error", readErr.Error()),
334				)
335				continue
336			}
337	
338			if content.Metadata.Agent != "" {
339				lastAgent = string(content.Metadata.Agent)
340			}
341	
342			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
343			if compacted == nil {
344				// tryCompactTranscript already logs for no-agent and compact-error cases;
345				// log the empty-transcript case here.
346				if len(content.Transcript) == 0 {
347					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
348						slog.String("checkpoint_id", string(info.CheckpointID)),
349						slog.Int("session_index", sessionIdx),
350					)
351				}
352				continue
353			}
354	
355			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
356				CheckpointID:      info.CheckpointID,
357				SessionID:         content.Metadata.SessionID,
358				CompactTranscript: compacted,
359			})
360			if updateErr != nil {
361				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
362					slog.String("checkpoint_id", string(info.CheckpointID)),
363					slog.Int("session_index", sessionIdx),
364					slog.String("error", updateErr.Error()),
365				)
366				continue
367			}
368	
369			backfilled++
370		}
371	
372		if backfilled == 0 {
373			if lastAgent != "" {
374				return fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
375			}
376			return fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
377		}
378	
379		fmt.Fprintf(out, "%s added transcript.jsonl for %d session(s)\n", prefix, backfilled)
380	
381		return nil
382	}
