384	func buildMigrateWriteOpts(content *checkpoint.SessionContent, info checkpoint.CommittedInfo) checkpoint.WriteCommittedOptions {
385		m := content.Metadata
386	
387		prompts := checkpoint.SplitPromptContent(content.Prompts)
388	
389		return checkpoint.WriteCommittedOptions{
390			CheckpointID:                info.CheckpointID,
391			SessionID:                   m.SessionID,
392			Strategy:                    m.Strategy,
393			Branch:                      m.Branch,
394			Transcript:                  content.Transcript,
395			Prompts:                     prompts,
396			FilesTouched:                m.FilesTouched,
397			CheckpointsCount:            m.CheckpointsCount,
398			Agent:                       m.Agent,
399			Model:                       m.Model,
400			TurnID:                      m.TurnID,
401			TokenUsage:                  m.TokenUsage,
402			SessionMetrics:              m.SessionMetrics,
403			InitialAttribution:          m.InitialAttribution,
404			Summary:                     m.Summary,
405			CheckpointTranscriptStart:   m.GetTranscriptStart(),
406			TranscriptIdentifierAtStart: m.TranscriptIdentifierAtStart,
407			IsTask:                      m.IsTask,
408			ToolUseID:                   m.ToolUseID,
409			AuthorName:                  "Entire Migration",
410			AuthorEmail:                 "migration@entire.dev",
411		}
412	}
