414	func tryCompactTranscript(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata) []byte {
415		if len(transcript) == 0 {
416			return nil
417		}
418		if m.Agent == "" {
419			logging.Warn(ctx, "compact transcript skipped: no agent type in checkpoint metadata",
420				slog.String("checkpoint_id", string(m.CheckpointID)),
421			)
422			return nil
423		}
424	
425		compacted, err := compact.Compact(transcript, compact.MetadataFields{
426			Agent:      string(m.Agent),
427			CLIVersion: versioninfo.Version,
428			StartLine:  m.GetTranscriptStart(),
429		})
430		if err != nil {
431			logging.Warn(ctx, "compact transcript generation failed during migration",
432				slog.String("checkpoint_id", string(m.CheckpointID)),
433				slog.String("agent", string(m.Agent)),
434				slog.String("error", err.Error()),
435			)
436			return nil
437		}
438		if len(compacted) == 0 {
439			logging.Warn(ctx, "transcript.jsonl generation produced no output",
440				slog.String("checkpoint_id", string(m.CheckpointID)),
441				slog.String("agent", string(m.Agent)),
442				slog.Int("input_bytes", len(transcript)),
443			)
444			return nil
445		}
446		return compacted
447	}
