449	// copyTaskMetadataToV2 copies task metadata files (subagent transcripts, checkpoint JSONs)
450	// from the v1 branch to the v2 /full/current ref via tree surgery.
451	func copyTaskMetadataToV2(repo *git.Repository, _ *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary) error {
452		// Resolve the v1 branch tree
453		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
454		if err != nil {
455			return err
456		}
457	
458		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
459		// Prefer attaching this tree to the latest session in v2.
460		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
461			if len(summary.Sessions) > 0 {
462				latestSessionIdx := len(summary.Sessions) - 1
463				if spliceErr := spliceTasksTreeToV2(repo, v2Store, cpID, latestSessionIdx, rootTasksTree.Hash); spliceErr != nil {
464					return fmt.Errorf("latest session task tree splice failed: %w", spliceErr)
465				}
466			}
467		}
468	
469		for sessionIdx := range len(summary.Sessions) {
470			sessionDir := strconv.Itoa(sessionIdx)
471			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
472			if sessionErr != nil {
473				continue
474			}
475	
476			tasksTree, tasksErr := sessionTree.Tree("tasks")
477			if tasksErr != nil {
478				continue // No tasks directory in this session
479			}
480	
481			if spliceErr := spliceTasksTreeToV2(repo, v2Store, cpID, sessionIdx, tasksTree.Hash); spliceErr != nil {
482				return fmt.Errorf("session %d task tree splice failed: %w", sessionIdx, spliceErr)
483			}
484		}
485	
486		return nil
487	}
