489	// resolveV1CheckpointTree reads the checkpoint subtree from the v1 branch.
490	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
491		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
492		ref, err := repo.Reference(refName, true)
493		if err != nil {
494			// Try remote tracking branch
495			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
496			ref, err = repo.Reference(remoteRefName, true)
497			if err != nil {
498				return nil, fmt.Errorf("v1 branch not found: %w", err)
499			}
500		}
501	
502		commit, err := repo.CommitObject(ref.Hash())
503		if err != nil {
504			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
505		}
506	
507		rootTree, err := commit.Tree()
508		if err != nil {
509			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
510		}
511	
512		cpTree, err := rootTree.Tree(cpID.Path())
513		if err != nil {
514			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
515		}
516	
517		return cpTree, nil
518	}
519	
520	func spliceTasksTreeToV2(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int, tasksTreeHash plumbing.Hash) error {
521		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
522		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
523		if err != nil {
524			return fmt.Errorf("failed to get v2 ref state: %w", err)
525		}
526		incomingTasksTree, err := repo.TreeObject(tasksTreeHash)
527		if err != nil {
528			return fmt.Errorf("failed to read tasks tree: %w", err)
529		}
530	
531		shardPrefix := string(cpID[:2])
532		shardSuffix := string(cpID[2:])
533		sessionDir := strconv.Itoa(sessionIdx)
534	
535		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
536			[]string{shardPrefix, shardSuffix, sessionDir, "tasks"},
537			incomingTasksTree.Entries,
538			checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
539		)
540		if err != nil {
541			return fmt.Errorf("tree surgery failed: %w", err)
542		}
543	
544		commitHash, err := checkpoint.CreateCommit(repo, newRoot, parentHash,
545			fmt.Sprintf("Add task metadata for %s\n", cpID),
546			"Entire Migration", "migration@entire.dev")
547		if err != nil {
548			return fmt.Errorf("failed to create commit: %w", err)
549		}
550	
551		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
552			return fmt.Errorf("failed to update ref %s: %w", refName, err)
553		}
554		return nil
555	}
