106	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, out io.Writer) (*migrateResult, error) {
107		v1List, err := v1Store.ListCommitted(ctx)
108		if err != nil {
109			return nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
110		}
111	
112		if len(v1List) == 0 {
113			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
114			return &migrateResult{}, nil
115		}
116	
117		fmt.Fprintln(out, "Migrating v1 checkpoints to v2...")
118		total := len(v1List)
119		result := &migrateResult{}
120	
121		for i, info := range v1List {
122			prefix := fmt.Sprintf("  [%d/%d] Migrating checkpoint %s...", i+1, total, info.CheckpointID)
123	
124			if migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, out, prefix); migrateErr != nil {
125				switch {
126				case errors.Is(migrateErr, errAlreadyMigrated):
127					fmt.Fprintf(out, "%s skipped (already in v2)\n", prefix)
128					result.skipped++
129				case errors.Is(migrateErr, errTranscriptNotGeneratable):
130					fmt.Fprintf(out, "%s in v2, but %s\n", prefix, migrateErr.Error())
131					result.skipped++
132				default:
133					fmt.Fprintf(out, "%s failed\n", prefix)
134					logging.Error(ctx, "checkpoint migration failed",
135						slog.String("checkpoint_id", string(info.CheckpointID)),
136						slog.String("error", migrateErr.Error()),
137					)
138					result.failed++
139				}
140				continue
141			}
142	
143			result.migrated++
144		}
145	
146		return result, nil
147	}
