149	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, out io.Writer, prefix string) error {
150		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
151		if err != nil {
152			return fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
153		}
154	
155		// Already in v2 — check if any aspect of sessions are missing and backfill
156		if existing != nil {
157			repaired, repairErr := repairPartialV2Checkpoint(ctx, repo, v1Store, v2Store, info, existing)
158			if repairErr != nil {
159				return repairErr
160			}
161	
162			currentV2, readCurrentErr := v2Store.ReadCommitted(ctx, info.CheckpointID)
163			if readCurrentErr != nil {
164				return fmt.Errorf("failed to re-read v2 checkpoint %s: %w", info.CheckpointID, readCurrentErr)
165			}
166			if currentV2 == nil {
167				return fmt.Errorf("v2 checkpoint %s disappeared during migration", info.CheckpointID)
168			}
169	
170			backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, currentV2, out, prefix)
171			if errors.Is(backfillErr, errAlreadyMigrated) && repaired {
172				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state\n", prefix)
173				return nil
174			}
175			if errors.Is(backfillErr, errTranscriptNotGeneratable) && repaired {
176				fmt.Fprintf(out, "%s repaired partial v2 checkpoint state (compact transcript not generated)\n", prefix)
177				return nil
178			}
179			return backfillErr
180		}
181	
182		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
183		if err != nil {
184			return fmt.Errorf("failed to read v1 summary: %w", err)
185		}
186		if summary == nil {
187			return fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
188		}
189	
190		compactFailed := false
191		shouldCopyTaskMetadata := false
192	
193		for sessionIdx := range len(summary.Sessions) {
194			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
195			if readErr != nil {
196				return fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
197			}
198			if content.Metadata.IsTask {
199				shouldCopyTaskMetadata = true
200			}
201	
202			opts := buildMigrateWriteOpts(content, info)
203	
204			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
205			if compacted != nil {
206				opts.CompactTranscript = compacted
207				opts.CompactTranscriptStart = computeCompactOffset(content.Transcript, compacted, content.Metadata)
208			} else if len(content.Transcript) > 0 {
209				compactFailed = true
210			}
211	
212			if writeErr := v2Store.WriteCommitted(ctx, opts); writeErr != nil {
213				return fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
214			}
215		}
216	
217		// Copy task metadata trees from v1 to v2 /full/current
218		if shouldCopyTaskMetadata {
219			if taskErr := copyTaskMetadataToV2(repo, v1Store, v2Store, info.CheckpointID, summary); taskErr != nil {
220				logging.Warn(ctx, "failed to copy task metadata to v2",
221					slog.String("checkpoint_id", string(info.CheckpointID)),
222					slog.String("error", taskErr.Error()),
223				)
224			}
225		}
226	
227		if compactFailed {
228			fmt.Fprintf(out, "%s done (compact transcript not generated)\n", prefix)
229		} else {
230			fmt.Fprintf(out, "%s done\n", prefix)
231		}
232	
233		return nil
234	}
