236	func repairPartialV2Checkpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (bool, error) {
237		repaired := false
238	
239		// Spot-check already present sessions: ensure required /full/current artifacts exist.
240		existingSessionCount := len(v2Summary.Sessions)
241		for sessionIdx := range existingSessionCount {
242			ok, checkErr := hasCurrentFullSessionArtifacts(repo, v2Store, info.CheckpointID, sessionIdx)
243			if checkErr != nil {
244				return false, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
245			}
246			if ok {
247				continue
248			}
249	
250			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
251			if readErr != nil {
252				return false, fmt.Errorf("failed to read v1 session %d while repairing v2: %w", sessionIdx, readErr)
253			}
254	
255			updateOpts := checkpoint.UpdateCommittedOptions{
256				CheckpointID: info.CheckpointID,
257				SessionID:    content.Metadata.SessionID,
258				Transcript:   content.Transcript,
259				Prompts:      checkpoint.SplitPromptContent(content.Prompts),
260				Agent:        content.Metadata.Agent,
261			}
262			if compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata); compacted != nil {
263				updateOpts.CompactTranscript = compacted
264			}
265	
266			if updateErr := v2Store.UpdateCommitted(ctx, updateOpts); updateErr != nil {
267				return false, fmt.Errorf("failed to repair v2 session %d: %w", sessionIdx, updateErr)
268			}
269			repaired = true
270		}
271	
272		return repaired, nil
273	}
