275	func hasCurrentFullSessionArtifacts(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int) (bool, error) {
276		_, rootTreeHash, err := v2Store.GetRefState(plumbing.ReferenceName(paths.V2FullCurrentRefName))
277		if err != nil {
278			return false, nil //nolint:nilerr // Missing /full/current ref means required artifacts are absent.
279		}
280	
281		rootTree, err := repo.TreeObject(rootTreeHash)
282		if err != nil {
283			return false, fmt.Errorf("failed to read /full/current tree: %w", err)
284		}
285	
286		sessionPath := fmt.Sprintf("%s/%d", cpID.Path(), sessionIdx)
287		sessionTree, err := rootTree.Tree(sessionPath)
288		if err != nil {
289			return false, nil //nolint:nilerr // Missing session path means artifacts are absent, not a hard error.
290		}
291	
292		hasTranscript := false
293		for _, entry := range sessionTree.Entries {
294			if entry.Name == paths.TranscriptFileName || strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
295				hasTranscript = true
296				break
297			}
298		}
299		if !hasTranscript {
300			return false, nil
301		}
302	
303		if _, err := sessionTree.File(paths.ContentHashFileName); err != nil {
304			return false, nil //nolint:nilerr // Missing content hash indicates incomplete /full/current artifacts.
305		}
306	
307		return true, nil
308	}
