310	// backfillCompactTranscripts checks sessions in an already-migrated v2 checkpoint
311	// for missing transcript.jsonl and attempts to generate + write them from v1 data.
312	// Returns errAlreadyMigrated if all sessions already have compact transcripts.
313	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary, out io.Writer, prefix string) error {
314		// Find sessions missing transcript.jsonl
315		var needsBackfill []int
316		for i, session := range v2Summary.Sessions {
317			if session.Transcript == "" {
318				needsBackfill = append(needsBackfill, i)
319			}
320		}
321	
322		if len(needsBackfill) == 0 {
323			return errAlreadyMigrated
324		}
325	
326		backfilled := 0
327		var lastAgent string
328	
329		for _, sessionIdx := range needsBackfill {
330			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
331			if readErr != nil {
332				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
333					slog.String("checkpoint_id", string(info.CheckpointID)),
334					slog.Int("session_index", sessionIdx),
335					slog.String("error", readErr.Error()),
336				)
337				continue
338			}
339	
340			if content.Metadata.Agent != "" {
341				lastAgent = string(content.Metadata.Agent)
342			}
343	
344			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
345			if compacted == nil {
346				// tryCompactTranscript already logs for no-agent and compact-error cases;
347				// log the empty-transcript case here.
348				if len(content.Transcript) == 0 {
349					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
350						slog.String("checkpoint_id", string(info.CheckpointID)),
351						slog.Int("session_index", sessionIdx),
352					)
353				}
354				continue
355			}
356	
357			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
358				CheckpointID:      info.CheckpointID,
359				SessionID:         content.Metadata.SessionID,
360				CompactTranscript: compacted,
361			})
362			if updateErr != nil {
363				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
364					slog.String("checkpoint_id", string(info.CheckpointID)),
365					slog.Int("session_index", sessionIdx),
366					slog.String("error", updateErr.Error()),
367				)
368				continue
369			}
370	
371			backfilled++
372		}
373	
374		if backfilled == 0 {
375			if lastAgent != "" {
376				return fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
377			}
378			return fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
379		}
380	
381		fmt.Fprintf(out, "%s added transcript.jsonl for %d session(s)\n", prefix, backfilled)
382	
383		return nil
384	}
