416	func tryCompactTranscript(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata) []byte {
417		if len(transcript) == 0 {
418			return nil
419		}
420		if m.Agent == "" {
421			logging.Warn(ctx, "compact transcript skipped: no agent type in checkpoint metadata",
422				slog.String("checkpoint_id", string(m.CheckpointID)),
423			)
424			return nil
425		}
426	
427		compacted, err := compact.Compact(transcript, compact.MetadataFields{
428			Agent:      string(m.Agent),
429			CLIVersion: versioninfo.Version,
430			StartLine:  m.GetTranscriptStart(),
431		})
432		if err != nil {
433			logging.Warn(ctx, "compact transcript generation failed during migration",
434				slog.String("checkpoint_id", string(m.CheckpointID)),
435				slog.String("agent", string(m.Agent)),
436				slog.String("error", err.Error()),
437			)
438			return nil
439		}
440		if len(compacted) == 0 {
441			logging.Warn(ctx, "transcript.jsonl generation produced no output",
442				slog.String("checkpoint_id", string(m.CheckpointID)),
443				slog.String("agent", string(m.Agent)),
444				slog.Int("input_bytes", len(transcript)),
445			)
446			return nil
447		}
448		return compacted
449	}
