451	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
452	// by comparing a full compact (startLine=0) against the scoped compact. The difference
453	// is the number of compact lines before this checkpoint's data.
454	func computeCompactOffset(fullTranscript, scopedCompact []byte, m checkpoint.CommittedMetadata) int {
455		startLine := m.GetTranscriptStart()
456		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
457			return 0
458		}
459	
460		fullCompacted, err := compact.Compact(fullTranscript, compact.MetadataFields{
461			Agent:      string(m.Agent),
462			CLIVersion: versioninfo.Version,
463			StartLine:  0,
464		})
465		if err != nil || len(fullCompacted) == 0 {
466			return 0
467		}
468	
469		fullLines := bytes.Count(fullCompacted, []byte{'\n'})
470		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
471		offset := fullLines - scopedLines
472		if offset < 0 {
473			return 0
474		}
475		return offset
476	}
