478	// copyTaskMetadataToV2 copies task metadata files (subagent transcripts, checkpoint JSONs)
479	// from the v1 branch to the v2 /full/current ref via tree surgery.
480	func copyTaskMetadataToV2(repo *git.Repository, _ *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary) error {
481		// Resolve the v1 branch tree
482		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
483		if err != nil {
484			return err
485		}
486	
487		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
488		// Prefer attaching this tree to the latest session in v2.
489		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
490			if len(summary.Sessions) > 0 {
491				latestSessionIdx := len(summary.Sessions) - 1
492				if spliceErr := spliceTasksTreeToV2(repo, v2Store, cpID, latestSessionIdx, rootTasksTree.Hash); spliceErr != nil {
493					return fmt.Errorf("latest session task tree splice failed: %w", spliceErr)
494				}
495			}
496		}
497	
498		for sessionIdx := range len(summary.Sessions) {
499			sessionDir := strconv.Itoa(sessionIdx)
500			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
501			if sessionErr != nil {
502				continue
503			}
504	
505			tasksTree, tasksErr := sessionTree.Tree("tasks")
506			if tasksErr != nil {
507				continue // No tasks directory in this session
508			}
509	
510			if spliceErr := spliceTasksTreeToV2(repo, v2Store, cpID, sessionIdx, tasksTree.Hash); spliceErr != nil {
511				return fmt.Errorf("session %d task tree splice failed: %w", sessionIdx, spliceErr)
512			}
513		}
514	
515		return nil
516	}
517	
518	// resolveV1CheckpointTree reads the checkpoint subtree from the v1 branch.
519	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
520		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
521		ref, err := repo.Reference(refName, true)
522		if err != nil {
523			// Try remote tracking branch
524			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
525			ref, err = repo.Reference(remoteRefName, true)
526			if err != nil {
527				return nil, fmt.Errorf("v1 branch not found: %w", err)
528			}
529		}
530	
531		commit, err := repo.CommitObject(ref.Hash())
532		if err != nil {
533			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
534		}
535	
536		rootTree, err := commit.Tree()
537		if err != nil {
538			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
539		}
540	
541		cpTree, err := rootTree.Tree(cpID.Path())
542		if err != nil {
543			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
544		}
545	
546		return cpTree, nil
547	}
548	
549	func spliceTasksTreeToV2(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int, tasksTreeHash plumbing.Hash) error {
550		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
551		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
552		if err != nil {
553			return fmt.Errorf("failed to get v2 ref state: %w", err)
554		}
555		incomingTasksTree, err := repo.TreeObject(tasksTreeHash)
556		if err != nil {
557			return fmt.Errorf("failed to read tasks tree: %w", err)
