	if result.failed > 0 {
		fmt.Fprintf(out, "%d checkpoint(s) failed to migrate. Check .entire/logs/ for details.\n", result.failed)
		return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
	}

	return nil
}

